import{_ as e,a0 as r,w as u,s as o,ao as s,I as n,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"為什麼程序員喜歡為 Linux 打包 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼程序員喜歡為 Linux 打包 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼程序員喜歡為 Linux 打包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼程序員喜歡為 Linux 打包 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20210214 Why programmers love Linux packaging","title":"為什麼程序員喜歡為 Linux 打包","tag":"202303","desc":""},"relativePath":"202303/20210214 Why programmers love Linux packaging.md","filePath":"[post].md"}'),x={name:"202303/20210214 Why programmers love Linux packaging.md"};function d(k,t,m,f,L,g){const l=r("Link");return u(),o("div",null,[t[25]||(t[25]=s('<h1 id="為什麼程序員喜歡為-linux-打包" tabindex="-1">為什麼程序員喜歡為 Linux 打包 <a class="header-anchor" href="#為什麼程序員喜歡為-linux-打包" aria-label="Permalink to “為什麼程序員喜歡為 Linux 打包”">​</a></h1><blockquote><p>程序員可以通過 Flatpak 輕鬆、穩定地發佈他們的軟件，讓他們專注於他們的激情工作：編程。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202303/29/231331qb9ye8gggeekvce1.jpg" alt=""></p><p>如今，人們比以往任何時候都喜愛 Linux。在這個系列中，我將分享使用 Linux 的 21 個不同理由。今天，我將談一談是什麼讓 Linux 的打包成為程序員的理想選擇。</p><p>程序員喜歡編程。這可能看起來是一個顯而易見的説法，但重要的是要明白，開發軟件所涉及的不僅僅是編寫代碼。它包括編譯、文檔、源代碼管理、安裝腳本、配置默認值、支持文件、交付格式等等。從一個空白的屏幕到一個可交付的軟件安裝程序，需要的不僅僅是編程，但大多數程序員寧願編程也不願打包。</p><h3 id="什麼是打包" tabindex="-1">什麼是打包？ <a class="header-anchor" href="#什麼是打包" aria-label="Permalink to “什麼是打包？”">​</a></h3><p>當食物被送到商店購買時，它是被包裝好的。當直接從農民或從環保的散裝或桶裝商店購買時，包裝是你所帶的任何容器。當從雜貨店購買時，包裝可能是一個紙板箱、塑料袋、一個鐵罐等等。</p><p>當軟件被提供給廣大計算機用户時，它也必須被打包起來。像食品一樣，軟件也有幾種打包方式。開源軟件可以不進行打包，因為用户在獲得原始代碼後，可以自己編譯和打包它。然而，打包也有好處，所以應用程序通常以某種特定於用户平台的格式交付。而這正是問題的開始，因為軟件包的格式並不只有一種。</p><p>對於用户來説，軟件包使安裝軟件變得容易，因為所有的工作都由系統的安裝程序完成。軟件被從軟件包中提取出來，並分發到操作系統中的適當位置。幾乎沒有任何出錯的機會。</p><p>然而，對於軟件開發者來説，打包意味着你必須學會如何創建一個包 —— 而且不僅僅是一個包，而是為你希望你的軟件可以安裝到的每一個操作系統創建一個獨特的包。更加複雜的是，每個操作系統都有多種打包格式和選項，有時甚至是不同的編程語言。</p><h3 id="為-linux-打包" tabindex="-1">為 Linux 打包 <a class="header-anchor" href="#為-linux-打包" aria-label="Permalink to “為 Linux 打包”">​</a></h3><p>傳統上，Linux 的打包方式似乎是非常多的。從 Fedora 衍生出來的 Linux 發行版，如 Red Hat 和 CentOS，默認使用 .rpm 包。Debian 和 Ubuntu（以及類似的）默認使用 .deb 包。其他發行版可能使用其中之一，或者兩者都不使用，選擇自定義的格式。當被問及時，許多 Linux 用户説，理想情況下，程序員根本不會為 Linux 打包他們的軟件，而是依靠每個發行版的軟件包維護者來創建軟件包。所有安裝在 Linux 系統上的軟件都應該來自該發行版的官方軟件庫。然而，目前還不清楚如何讓你的軟件可靠地被一個發行版打包和包含，更不用説所有的發行版了。</p><h3 id="linux-的-flatpak" tabindex="-1">Linux 的 Flatpak <a class="header-anchor" href="#linux-的-flatpak" aria-label="Permalink to “Linux 的 Flatpak”">​</a></h3><p>Flatpak 打包系統是為了統一和去中心化 Linux 作為開發者的交付目標而推出的。通過 Flatpak，無論是開發者還是其他人（Linux 社區的成員、不同的開發者、Flatpak 團隊成員或其他任何人）都可以自由地打包軟件。然後他們可以將軟件包提交給 Flathub，或者選擇自我託管軟件包，並將其提供給幾乎任何 Linux 發行版。Flatpak 系統適用於所有 Linux 發行版，所以針對一個發行版就等於針對所有發行版。</p><h3 id="flatpak-技術如何工作" tabindex="-1">Flatpak 技術如何工作 <a class="header-anchor" href="#flatpak-技術如何工作" aria-label="Permalink to “Flatpak 技術如何工作”">​</a></h3><p>Flatpak 具有普遍吸引力的秘密是一個標準基礎。Flatpak 系統允許開發者引用一套通用的軟件開發者工具包（SDK）模組。這些模組由 Flatpak 系統的維護者進行打包和管理。當你安裝 Flatpak 時，SDK 會根據需要被拉入，以確保與你的系統兼容。任何特定的 SDK 只需要一次，因為它所包含的庫可以在任何 Flatpak 中共享。</p><p>如果開發者需要一個尚未包含在現有 SDK 中的庫，開發者可以在 Flatpak 中添加該庫。</p>',17)),n("p",null,[t[1]||(t[1]=a("結果不言自明。用户可以從一個叫做 ",-1)),i(l,{href:"https://flatpak.org/setup/"},{default:p(()=>[...t[0]||(t[0]=[a("Flathub",-1)])]),_:1}),t[2]||(t[2]=a(" 的中央倉庫在任何 Linux 發行版上安裝數百個軟件包。",-1))]),t[26]||(t[26]=n("h3",{id:"開發者如何使用-flatpak",tabindex:"-1"},[a("開發者如何使用 Flatpak "),n("a",{class:"header-anchor",href:"#開發者如何使用-flatpak","aria-label":"Permalink to “開發者如何使用 Flatpak”"},"​")],-1)),n("p",null,[t[6]||(t[6]=a("Flatpak 被設計成可重複的，所以構建過程很容易被集成到 CI/CD 工作流程中。Flatpak 是在一個 ",-1)),i(l,{href:"https://www.redhat.com/sysadmin/yaml-beginners"},{default:p(()=>[...t[3]||(t[3]=[a("YAML",-1)])]),_:1}),t[7]||(t[7]=a(" 或 JSON 清單文件中定義的。你可以按照我的 ",-1)),i(l,{href:"https://opensource.com/article/19/10/how-build-flatpak-packaging"},{default:p(()=>[...t[4]||(t[4]=[a("介紹性文章",-1)])]),_:1}),t[8]||(t[8]=a(" 創建你的第一個 Flatpak，你也可以在 ",-1)),i(l,{href:"https://docs.flatpak.org/en/latest/index.html"},{default:p(()=>[...t[5]||(t[5]=[a("docs.flatpak.org",-1)])]),_:1}),t[9]||(t[9]=a(" 閲讀完整的文檔。",-1))]),t[27]||(t[27]=n("h3",{id:"linux-讓它變得簡單",tabindex:"-1"},[a("Linux 讓它變得簡單 "),n("a",{class:"header-anchor",href:"#linux-讓它變得簡單","aria-label":"Permalink to “Linux 讓它變得簡單”"},"​")],-1)),t[28]||(t[28]=n("p",null,"在 Linux 上創建軟件很容易，為 Linux 打包也很簡單，而且可以自動化。如果你是一個程序員，Linux 使你很容易忘記打包這件事，因為它只需要針對一個系統，並可以整合到你的構建過程中。",-1)),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[11]||(t[11]=a("via: ",-1)),i(l,{href:"https://opensource.com/article/21/2/linux-packaging"},{default:p(()=>[...t[10]||(t[10]=[a("https://opensource.com/article/21/2/linux-packaging",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=a("作者：",-1)),i(l,{href:"https://opensource.com/users/seth"},{default:p(()=>[...t[12]||(t[12]=[a("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=a(" 選題：",-1)),i(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[13]||(t[13]=[a("lujun9972",-1)])]),_:1}),t[18]||(t[18]=a(" 譯者：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[14]||(t[14]=[a("wxy",-1)])]),_:1}),t[19]||(t[19]=a(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[15]||(t[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=a("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[20]||(t[20]=[a("LCTT",-1)])]),_:1}),t[23]||(t[23]=a(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:p(()=>[...t[21]||(t[21]=[a("Linux中國",-1)])]),_:1}),t[24]||(t[24]=a(" 榮譽推出",-1))])])}const h=e(x,[["render",d]]);export{T as __pageData,h as default};
